#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> blockSums(max_threads, 0LL);
    std::vector<long long> blockOffsets(max_threads, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const int chunk = (n + T - 1) / T;
        const int start = tid * chunk;
        const int end   = (start + chunk < n) ? (start + chunk) : n;

        long long localSum = 0;
        for (int i = start; i < end; ++i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }
        blockSums[tid] = localSum;

        #pragma omp barrier

        #pragma omp single
        {
            long long acc = 0;
            for (int t = 0; t < T; ++t) {
                blockOffsets[t] = acc;
                acc += blockSums[t];
            }
        }

        #pragma omp barrier

        const long long add = blockOffsets[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
        }
    }
}
