#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        // Partition [0, n) into contiguous blocks deterministically.
        const int start = (tid * n) / T;
        const int end   = ((tid + 1) * n) / T; // exclusive

        // Compute local prefix sum within this block.
        long long localSum = 0;
        for (int i = start; i < end; ++i) {
            localSum += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(localSum);
        }

        // Compute offset = sum of all prior blocks.
        long long offset = 0;
        for (int p = 0; p < tid; ++p) {
            const int ps = (p * n) / T;
            const int pe = ((p + 1) * n) / T;
            for (int i = ps; i < pe; ++i) {
                offset += static_cast<long long>(x[i]);
            }
        }

        // Apply offset to this block.
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
        }
    }
}
